interface InvoiceItem {
  id: number;
  numero_nota: string;
  fornecedor: string;
  data_nota: string | null;
  created_at: string;
  valor_total: number;
  status: string;
  itens_nota_fiscal?: {
    id: number;
    nome_produto: string;
    quantidade: number;
    valor_unitario: number;
    subtotal: number;
    categoria?: string;
  }[];
}

interface InvoiceAnalyticsDashboardProps {
  invoices: InvoiceItem[];
}

export function InvoiceAnalyticsDashboard({
  invoices,
}: InvoiceAnalyticsDashboardProps) {
  const today = new Date();
  const defaultStart = startOfMonth(today);

  // State for Date Range Filter
  const [dateRange, setDateRange] = useState<DateRange | undefined>({
    from: defaultStart,
    to: today,
  });

  const [selectedMetric, setSelectedMetric] = useState<string | null>(null);
  const [drilldownCategory, setDrilldownCategory] = useState<CategoriaNF | null>(null);

  // --- Filter Logic ---
  const filteredInvoices = useMemo(() => {
    if (!dateRange?.from) return invoices;

    return invoices.filter((invoice) => {
      const dateStr = invoice.data_nota || invoice.created_at;
      if (!dateStr) return false;
      const date = parseISO(dateStr);
      if (!isValid(date)) return false;

      const from = dateRange.from as Date;
      const to = dateRange.to || dateRange.from || new Date();

      const target = date.getTime();
      const startStr = new Date(from).setHours(0, 0, 0, 0);
      const endStr = new Date(to).setHours(23, 59, 59, 999);

      return target >= startStr && target <= endStr;
    });
  }, [invoices, dateRange]);

  // --- Analytics Logic ---
  const analytics = useMemo(() => {
    const totalRecords = filteredInvoices.length;
    const totalValue = filteredInvoices.reduce(
      (acc, curr) => acc + (Number(curr.valor_total) || 0),
      0,
    );

    // Daily Averages
    const daysDiff =
      dateRange?.from && dateRange?.to
        ? Math.max(1, differenceInDays(dateRange.to, dateRange.from) + 1)
        : 30;

    const avgDailyVal = totalValue / daysDiff;
    const avgTicket = totalRecords > 0 ? totalValue / totalRecords : 0;

    // Grouping Logic
    const isDailyGroup = daysDiff < 60;

    const bySupplierValue: Record<string, number> = {};

