const isMobile = useIsMobile();
const { canViewNotasFiscais } = usePermissions();
const navigate = useNavigate();

import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Badge } from '@/shared/ui/badge';
import { Search, Filter, ArrowUpDown, X, CalendarIcon } from 'lucide-react';
import {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from '@/shared/ui/drawer';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { cn } from '@/shared/lib/utils';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface FilterState {
  searchTerm: string;
  dateStart: string;
  dateEnd: string;
  statusFilter: 'all' | 'processando' | 'processada' | 'erro';
  sortAsc: boolean;
}

interface NotaFiltersProps {
  filters: FilterState;
  onFilterChange: (key: keyof FilterState, value: any) => void;
}

export function NotaFilters({ filters, onFilterChange }: NotaFiltersProps) {
  const isMobile = useIsMobile();

  const activeFiltersCount = [
    filters.dateStart,
    filters.dateEnd,
    filters.statusFilter !== 'all',
  ].filter(Boolean).length;

  const FilterContent = () => (
    <div className="space-y-6">
      {/* Status */}
      <div className="space-y-2">
        <Label className="text-[#57715B] font-semibold">Status</Label>
        <div className="flex flex-wrap gap-2">
          {[
            { label: 'Todos', value: 'all' },
            { label: 'Processando', value: 'processando' },
            { label: 'Processada', value: 'processada' },
            { label: 'Erro', value: 'erro' },
          ].map((opt) => (
            <Badge
              key={opt.value}
              variant="outline"
              className={cn(
                'cursor-pointer px-4 py-1.5 rounded-full text-sm transition-all border-[#57715B]/20',
                filters.statusFilter === (opt.value as any)
                  ? 'bg-[#57715B] text-white border-[#57715B] shadow-md shadow-[#57715B]/20'
                  : 'hover:bg-[#57715B]/10 bg-transparent text-[#57715B]',
              )}
              onClick={() => onFilterChange('statusFilter', opt.value)}
            >
              {opt.label}
            </Badge>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="date-start" className="text-[#57715B] font-semibold">
            De
          </Label>
          <div className="relative">
            <Input data-mia-field="date-start"
              type="date"
              id="date-start"
              className="w-full rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
              value={filters.dateStart}
              onChange={(e) => onFilterChange('dateStart', e.target.value)}
            />
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="date-end" className="text-[#57715B] font-semibold">
            Até
          </Label>
          <Input data-mia-field="date-end"
            type="date"
            id="date-end"
            className="w-full rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
            value={filters.dateEnd}
            onChange={(e) => onFilterChange('dateEnd', e.target.value)}
          />
        </div>
      </div>

      <div className="flex items-center justify-between pt-2">
        <Label className="text-[#57715B] font-semibold">Ordenação</Label>
        <Button
          variant="outline"
          size="sm"
          className="rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 hover:text-[#57715B]"
          onClick={() => onFilterChange('sortAsc', !filters.sortAsc)}
        >
          <ArrowUpDown className="mr-2 h-4 w-4" />
          {filters.sortAsc ? 'Mais antigas' : 'Mais recentes'}
        </Button>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col md:flex-row gap-3">
      {/* Search Bar - Always Visible */}
      <div className="relative flex-1">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[#57715B]/60" />
        <Input
          placeholder="Buscar por fornecedor ou número..."
          className="pl-10 h-10 rounded-full border-[#57715B]/20 bg-white/40 dark:bg-black/20 backdrop-blur-sm focus:border-[#57715B] focus:ring-[#57715B]/10 transition-all placeholder:text-[#57715B]/40 text-[#2D362E] dark:text-[#E6DCCF]"
          value={filters.searchTerm}
          onChange={(e) => onFilterChange('searchTerm', e.target.value)}
        />
        {filters.searchTerm && (
          <button
            onClick={() => onFilterChange('searchTerm', '')}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-[#57715B]/60 hover:text-[#57715B]"
          >
            <X className="h-4 w-4" />
          </button>
        )}
      </div>

      {/* Filter Button with Drawer (Mobile) or Popover (Desktop) */}
      {isMobile ? (
        <Drawer>
          <DrawerTrigger asChild>
            <Button
              variant="outline"
              className={cn(
                'h-10 px-4 rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 active:scale-95 transition-all',
                activeFiltersCount > 0 && 'bg-[#57715B]/10 border-[#57715B]',
              )}
            >
              <Filter className="h-4 w-4 mr-2" />
              Filtros
              {activeFiltersCount > 0 && (
                <span className="absolute -top-1 -right-1 h-3 w-3 bg-[#C5A065] rounded-full border-2 border-background animate-pulse" />
              )}
            </Button>
          </DrawerTrigger>
          <DrawerContent className="rounded-t-[2rem]">
            <DrawerHeader className="text-left">
              <DrawerTitle className="text-[#2D362E] text-xl">
                Filtros Avançados
              </DrawerTitle>
              <DrawerDescription className="text-[#57715B]/70">
                Refine sua busca por data e status
              </DrawerDescription>
            </DrawerHeader>
            <div className="p-4 pb-0">
              <FilterContent />
            </div>
            <DrawerFooter className="pt-4">
              <DrawerClose asChild>
                <Button className="w-full rounded-full bg-[#57715B] hover:bg-[#4A614D] text-white font-bold shadow-lg shadow-[#57715B]/20 h-12">
                  Aplicar Filtros
                </Button>
              </DrawerClose>
            </DrawerFooter>
          </DrawerContent>
        </Drawer>
      ) : (
        <Popover>
          <PopoverTrigger asChild>
            <Button
              variant="outline"
              className={cn(
                'h-10 px-4 rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 transition-all',
                activeFiltersCount > 0 && 'bg-[#57715B]/10 border-[#57715B]',
              )}
            >
              <Filter className="h-4 w-4 mr-2" />
              Filtros
              {activeFiltersCount > 0 && (
                <span className="ml-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-[#57715B] text-xs font-bold text-white shadow-sm">
                  {activeFiltersCount}
                </span>
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent
            className="w-80 p-4 rounded-2xl border-[#57715B]/10 shadow-xl bg-white/95 backdrop-blur-md"
            align="end"
          >
            <div className="space-y-4">
              <h4 className="font-bold leading-none text-[#2D362E]">
                Filtros Avançados
              </h4>
              <div className="h-px bg-[#57715B]/10" />
              <FilterContent />
              <div className="pt-2 flex justify-end">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => {
                    onFilterChange('dateStart', '');
                    onFilterChange('dateEnd', '');
                    onFilterChange('statusFilter', 'all');
                  }}
                  className="text-[#57715B] hover:bg-[#57715B]/10 rounded-full"
                >
                  Limpar
                </Button>
              </div>
            </div>
          </PopoverContent>
        </Popover>
      )}
    </div>
  );
}

