import { useMemo } from 'react';
import { useMiaActions } from '@/hooks/useMiaActions';
import type { MiaActionHandler } from '@/types/mia';

export interface NotasFiscaisMiaInterface {
  // Filtros
  setSearchTerm: (v: string) => void;
  setStatusFilter: (v: 'all' | 'processando' | 'processada' | 'erro') => void;
  setInvoiceDateStart: (v: string) => void;
  setInvoiceDateEnd: (v: string) => void;
  setSortAsc: (v: boolean | ((prev: boolean) => boolean)) => void;

  // Visualizações
  setIsAnalyticsView: (v: boolean) => void;
  setIsUploadOpen: (v: boolean) => void;

  // Modais
  setSelectedNota: (v: any) => void;
  setIsDetailsModalOpen: (v: boolean) => void;
  setIsEditModalOpen: (v: boolean) => void;
  setIsReportsModalOpen: (v: boolean) => void;

  // Dados para lookup
  notas: any[];
}

export function useMiaNotasFiscaisActions(iface: NotasFiscaisMiaInterface): void {
  const {
    setSearchTerm,
    setStatusFilter,
    setInvoiceDateStart,
    setInvoiceDateEnd,
    setSortAsc,
    setIsAnalyticsView,
    setIsUploadOpen,
    setSelectedNota,
    setIsDetailsModalOpen,
    setIsEditModalOpen,
    setIsReportsModalOpen,
    notas,
  } = iface;

  const findNota = (data: Record<string, any> | undefined) => {
    if (!data) return null;
    if (data.nota_id) {
      return notas.find((n: any) => n.id === data.nota_id) || null;
    }
    if (data.fornecedor) {
      const term = String(data.fornecedor).toLowerCase();
      return notas.find((n: any) => n.fornecedor?.toLowerCase().includes(term)) || null;
    }
    if (data.numero_nota) {
      return notas.find((n: any) => n.numero_nota === data.numero_nota) || null;
    }
    return null;
  };

  const handlers = useMemo<Record<string, MiaActionHandler>>(() => ({
    // ── Filtro combinado ──
    notas_filter: {
      id: 'notas_filter',
      description: 'Aplicar filtros em notas fiscais (busca, status, período)',
      execute: (data) => {
        if (!data) return;
        if (data.search !== undefined) setSearchTerm(data.search);
        if (data.status !== undefined) setStatusFilter(data.status);
        if (data.date_start !== undefined) setInvoiceDateStart(data.date_start);
        if (data.date_end !== undefined) setInvoiceDateEnd(data.date_end);
      },
    },

    // ── Busca por texto ──
    notas_set_search: {
      id: 'notas_set_search',
      description: 'Definir termo de busca para filtrar notas fiscais por fornecedor ou número',
      execute: (data) => {
        if (data?.search !== undefined) setSearchTerm(data.search);
      },
    },

    // ── Filtro de status ──
    notas_set_status: {
      id: 'notas_set_status',
      description: 'Filtrar notas fiscais por status (all, processando, processada, erro)',
      execute: (data) => {
        if (data?.status !== undefined) setStatusFilter(data.status);
      },
    },

    // ── Período de datas ──
    notas_date_range: {
      id: 'notas_date_range',
      description: 'Definir período de datas para filtrar notas fiscais (formato YYYY-MM-DD)',
      execute: (data) => {
        if (!data) return;
        if (data.date_start !== undefined) setInvoiceDateStart(data.date_start);
        if (data.date_end !== undefined) setInvoiceDateEnd(data.date_end);
      },
    },

    // ── Visualização analítica ──
    notas_toggle_analytics: {
      id: 'notas_toggle_analytics',
      description: 'Alternar entre visão de lista e dashboard analítico de notas fiscais',
      execute: (data) => {
        const show = data?.show ?? true;
        setIsAnalyticsView(Boolean(show));
      },
    },

    // ── Painel de upload ──
    notas_toggle_upload: {
      id: 'notas_toggle_upload',
      description: 'Abrir ou fechar painel de upload de notas fiscais',
      execute: (data) => {
        const open = data?.open ?? true;
        setIsUploadOpen(Boolean(open));
      },
    },

    // ── Detalhes da nota ──
    notas_open_details: {
      id: 'notas_open_details',
      description: 'Abrir modal de detalhes de uma nota fiscal por ID, fornecedor ou número',
      execute: (data) => {
        const nota = findNota(data);
        if (nota) {
          setSelectedNota(nota);
          setIsDetailsModalOpen(true);
        }
      },
    },

    // ── Editar nota ──
    notas_open_edit: {
      id: 'notas_open_edit',
      description: 'Abrir modal de edição de uma nota fiscal por ID, fornecedor ou número',
      execute: (data) => {
        const nota = findNota(data);
        if (nota) {
          setSelectedNota(nota);
          setIsEditModalOpen(true);
        }
      },
    },

    // ── Relatórios ──
    notas_open_reports: {
      id: 'notas_open_reports',
      description: 'Abrir modal de relatórios de notas fiscais',
      execute: () => {
        setIsReportsModalOpen(true);
      },
    },

    // ── Ordenação ──
    notas_toggle_sort: {
      id: 'notas_toggle_sort',
      description: 'Alternar ordenação de notas fiscais (ascendente/descendente por data)',
      execute: (data) => {
        if (data?.ascending !== undefined) {
          setSortAsc(Boolean(data.ascending));
        } else {
          setSortAsc((prev: boolean) => !prev);
        }
      },
    },

    // ── Limpar filtros ──
    clear_filters: {
      id: 'clear_filters',
      description: 'Limpar todos os filtros de notas fiscais',
      execute: () => {
        setSearchTerm('');
        setStatusFilter('all');
      },
    },
  }), [
    setSearchTerm,
    setStatusFilter,
    setInvoiceDateStart,
    setInvoiceDateEnd,
    setSortAsc,
    setIsAnalyticsView,
    setIsUploadOpen,
    setSelectedNota,
    setIsDetailsModalOpen,
    setIsEditModalOpen,
    setIsReportsModalOpen,
    notas,
  ]);

  useMiaActions('/notas-fiscais', handlers);
}

