// Grouping Logic
const isDailyGroup = daysDiff < 60;

const bySupplierValue: Record<string, number> = {};
const supplierDisplayNames: Record<string, string> = {};
const byCategoryValue: Record<string, number> = {};
const byProductValue: Record<string, number> = {};
const byCategoryProducts: Record<string, Record<string, { qtd: number; valor: number; fornecedores: Set<string> }>> = {};
const byTime: Record<
  string,
  { date: string; value: number; count: number }
> = {};

// Flatten items for product/category analysis
let totalItems = 0;

filteredInvoices.forEach((invoice) => {
  const dateStr = invoice.data_nota || invoice.created_at;
  const date = dateStr ? parseISO(dateStr) : new Date();
  const timeKey = isDailyGroup
    ? format(date, 'yyyy-MM-dd')
    : format(date, 'yyyy-MM');

  const val = Number(invoice.valor_total) || 0;
