```

10. Remove now-unused imports: `Popover, PopoverContent, PopoverTrigger` from '@/shared/ui/popover', `Calendar` from '@/shared/ui/calendar', `DateRange` from 'react-day-picker', `CalendarIcon` from lucide, `startOfYear, startOfMonth, subDays, isEqual` from 'date-fns' (check all usages before removing each — only remove if truly unused).

---

## FILE 4: `src/features/notas-fiscais/ui/NotasFiscais.page.tsx`

This is the main file (2047+ lines). Read it carefully before making changes.

**State changes:**

1. Remove these state variables:
   - `const [dateStart, setDateStart] = useState("");`
   - `const [dateEnd, setDateEnd] = useState("");`
   - `const [dateRange, setDateRange] = useState<DateRange | undefined>({...});`
   - `const [invoiceDateStart, setInvoiceDateStart] = useState(startOfMonthStr);`
   - `const [invoiceDateEnd, setInvoiceDateEnd] = useState(todayStr);`

2. Add these state variables (right after the `notas` useState):
```typescript
type DateFilterType = 'data_recebimento' | 'created_at' | 'data_nota' | 'data_vencimento';
const [dateFilterType, setDateFilterType] = useState<DateFilterType>('data_recebimento');
const [dateFilterRange, setDateFilterRange] = useState<DateRange | undefined>({
  from: startOfMonth,
  to: today
});
```
Note: `startOfMonth` and `today` are already local variables in the component (lines 177-178 of the original).

3. Add derived strings for query and effects (right after the new state vars):
```typescript
const dfStart = dateFilterRange?.from ? format(dateFilterRange.from, 'yyyy-MM-dd') : '';
const dfEnd = dateFilterRange?.to ? format(dateFilterRange.to, 'yyyy-MM-dd') : '';
```

**Query changes** in `loadNotas` function:

4. Remove these four condition blocks:
```typescript
if (dateStart) {
  query = query.gte('created_at', dateStart);
}
// ...
if (dateEnd) {
  query = query.lte('created_at', dateEnd);
}
if (invoiceDateStart) {
  query = query.gte('data_nota', invoiceDateStart);
}
if (invoiceDateEnd) {
  query = query.lte('data_nota', invoiceDateEnd);
}
```

5. Replace with ONE unified condition:
```typescript
if (dfStart) {
  query = query.gte(dateFilterType, dateFilterType === 'created_at' ? dfStart : dfStart);
}
if (dfEnd) {
  if (dateFilterType === 'created_at') {
    query = query.lte('created_at', dfEnd + 'T23:59:59');
  } else {
    query = query.lte(dateFilterType, dfEnd);
  }
}
```

6. Update telemetry in `loadNotas` — replace `'nota.periodo': \`${invoiceDateStart}_${invoiceDateEnd}\`` with:
```typescript
'nota.periodo': `${dfStart}_${dfEnd}`,
'nota.filtro_tipo': dateFilterType,
```
(Same update in the catch block error telemetry).

**useEffect changes:**

7. Remove the useEffect that synced `dateRange` to `invoiceDateStart/invoiceDateEnd` (the one starting at line ~1178 with `if (dateRange?.from)`).

8. Update the reload useEffect — replace deps `[searchTerm, dateStart, dateEnd, invoiceDateStart, invoiceDateEnd, statusFilter, sortAsc, selectedStore?.id]` with:
```typescript
[searchTerm, dfStart, dfEnd, dateFilterType, statusFilter, sortAsc, selectedStore?.id]
```

**MIA hook update:**

9. Update `useMiaNotasFiscaisActions` call — replace `setInvoiceDateStart, setInvoiceDateEnd` with the new setters. Since MIA works with `string` dates and the state now uses `DateRange`, provide adapter functions:
```typescript
useMiaNotasFiscaisActions({
  setSearchTerm,
  setStatusFilter,
  setDateFilterStart: (v: string) => {
    setDateFilterRange(prev => ({
      from: v ? new Date(v + 'T12:00:00') : undefined,
      to: prev?.to,
    }));
  },
  setDateFilterEnd: (v: string) => {
    setDateFilterRange(prev => ({
      from: prev?.from,
      to: v ? new Date(v + 'T12:00:00') : undefined,
    }));
  },
  setDateFilterType,
  setSortAsc,
  setIsAnalyticsView,
  setIsUploadOpen,
  setSelectedNota,
  setIsDetailsModalOpen,
  setIsEditModalOpen,
  setIsReportsModalOpen,
  notas,
});
```

**Header UI changes:**

10. Replace the date filter section in the header. Find and remove the block:
```tsx
{/* Page-Level Date Filter (Invoice Date) */}
<div className="flex items-center gap-2">
  <Popover>
    ...entire popover with Calendar...
  </Popover>
</div>
```

Replace with this new unified filter (import `subDays, startOfYear, endOfMonth, subMonths` from 'date-fns' — add them to the existing import):
```tsx
{/* Unified Date Filter */}
<div className="flex flex-col gap-2">
  <div className="flex items-center gap-2">
    <Select
      value={dateFilterType}
      onValueChange={(v) => setDateFilterType(v as DateFilterType)}
    >
      <SelectTrigger className="w-[160px] h-10 rounded-xl border-[#57715B]/10 bg-white/50 dark:bg-black/20 backdrop-blur-sm text-sm font-medium text-[#57715B] dark:text-[#8FA893]">
        <SelectValue />
      </SelectTrigger>
      <SelectContent className="rounded-xl border-[#57715B]/10">
        <SelectItem value="data_recebimento">Recebimento</SelectItem>
        <SelectItem value="created_at">Lançamento</SelectItem>
        <SelectItem value="data_nota">Emissão</SelectItem>
        <SelectItem value="data_vencimento">Vencimento</SelectItem>
      </SelectContent>
    </Select>

    <Popover>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          className={cn(
            "w-full md:w-[230px] justify-start text-left font-normal bg-white/50 dark:bg-black/20 border-[#57715B]/10 hover:bg-white/80 dark:hover:bg-black/40 backdrop-blur-sm rounded-xl",
            !dateFilterRange && "text-muted-foreground"
          )}
        >
          <CalendarIcon className="mr-2 h-4 w-4 text-[#57715B]" />
          {dateFilterRange?.from ? (
            dateFilterRange.to ? (
              <span className="truncate text-sm">
                {format(dateFilterRange.from, "dd/MM/yyyy", { locale: ptBR })} –{" "}
                {format(dateFilterRange.to, "dd/MM/yyyy", { locale: ptBR })}
              </span>
            ) : (
              format(dateFilterRange.from, "dd/MM/yyyy", { locale: ptBR })
            )
          ) : (
            <span>Selecione um período</span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0 border-[#57715B]/10 rounded-xl shadow-xl" align="end">
        <Calendar
          initialFocus
          mode="range"
          defaultMonth={dateFilterRange?.from}
          selected={dateFilterRange}
          onSelect={setDateFilterRange}
          numberOfMonths={2}
          locale={ptBR}
          className="p-3"
        />
      </PopoverContent>
    </Popover>
  </div>

  <div className="flex items-center gap-1 flex-wrap">
    {([
      { label: 'Hoje', from: today, to: today },
      { label: '7 dias', from: subDays(today, 6), to: today },
      { label: 'Este Mês', from: startOfMonth, to: today },
      { label: 'Mês Anterior', from: startOfMonth__prevMonth, to: endOfMonth__prevMonth },
      { label: 'Este Ano', from: startOfYear(today), to: today },
    ] as { label: string; from: Date; to: Date }[]).map((p) => {
      const active =
        dateFilterRange?.from &&
        dateFilterRange?.to &&
        format(dateFilterRange.from, 'yyyy-MM-dd') === format(p.from, 'yyyy-MM-dd') &&
        format(dateFilterRange.to, 'yyyy-MM-dd') === format(p.to, 'yyyy-MM-dd');
      return (
        <Button
          key={p.label}
          variant="ghost"
          size="sm"
          onClick={() => setDateFilterRange({ from: p.from, to: p.to })}
          className={cn(
            "rounded-full text-xs h-7 px-3 font-medium border",
            active
              ? "bg-[#57715B] text-white border-[#57715B]"
              : "text-[#57715B] hover:bg-[#57715B]/10 bg-white/40 dark:bg-black/20 border-[#57715B]/10"
          )}
        >
          {p.label}
        </Button>
      );
    })}
  </div>
</div>
```

For the preset dates, define these BEFORE the return statement (near the `today` and `startOfMonth` declarations, lines ~177):
```typescript
const prevMonthDate = new Date(today.getFullYear(), today.getMonth() - 1, 1);
const startOfMonth__prevMonth = new Date(today.getFullYear(), today.getMonth() - 1, 1);
const endOfMonth__prevMonth = new Date(today.getFullYear(), today.getMonth(), 0);
```
(Use descriptive variable names — `prevMonthStart` and `prevMonthEnd` are cleaner).

