  DrawerFooter: ({ children }: any) => <div>{children}</div>,
  DrawerClose: ({ children }: any) => <>{children}</>,
}));

vi.mock('@/shared/ui/popover', () => ({
  Popover: ({ children }: any) => <>{children}</>,
  PopoverTrigger: ({ children }: any) => <>{children}</>,
  PopoverContent: ({ children }: any) => <div>{children}</div>,
}));

// ── activeFiltersCount helper tests ───────────────────────────────────────

const computeActiveFiltersCount = (filters: {
  dateStart: string;
  dateEnd: string;
  statusFilter: string;
}) =>
  [filters.dateStart, filters.dateEnd, filters.statusFilter !== 'all'].filter(
    Boolean,
  ).length;

describe('NotaFilters — activeFiltersCount helper', () => {
  it('returns 0 when no active filters', () => {
    expect(
      computeActiveFiltersCount({
        dateStart: '',
        dateEnd: '',
        statusFilter: 'all',
      }),
    ).toBe(0);
  });

  it('returns 1 when only dateStart is set', () => {
    expect(
      computeActiveFiltersCount({
        dateStart: '2025-01-01',
        dateEnd: '',
        statusFilter: 'all',
      }),
    ).toBe(1);
  });

  it('returns 2 when start and end date are set', () => {
    expect(
      computeActiveFiltersCount({
        dateStart: '2025-01-01',
        dateEnd: '2025-01-31',
        statusFilter: 'all',
      }),
    ).toBe(2);
  });

  it('returns 3 when all filters active', () => {
    expect(
      computeActiveFiltersCount({
        dateStart: '2025-01-01',
        dateEnd: '2025-01-31',
        statusFilter: 'processada',
      }),
    ).toBe(3);
  });

  it('returns 1 when only statusFilter is active', () => {
    expect(
      computeActiveFiltersCount({
        dateStart: '',
        dateEnd: '',
        statusFilter: 'erro',
      }),
    ).toBe(1);
  });
});

// ── Render tests ───────────────────────────────────────────────────────────

const makeFilters = (overrides = {}) => ({
  searchTerm: '',
  dateStart: '',
  dateEnd: '',
  statusFilter: 'all' as const,
  sortAsc: false,
  ...overrides,
});

describe('NotaFilters — render', () => {
  it('renders the search input', async () => {
    const { NotaFilters } = await import('./NotaFilters');
    const filters = makeFilters();
    render(<NotaFilters filters={filters} onFilterChange={vi.fn()} />);
    expect(
      screen.getByPlaceholderText(/buscar por fornecedor/i),
    ).toBeInTheDocument();
  });

  it('renders the filter button', async () => {
    const { NotaFilters } = await import('./NotaFilters');
    const filters = makeFilters();
    render(<NotaFilters filters={filters} onFilterChange={vi.fn()} />);
    expect(
      screen.getByRole('button', { name: /filtros/i }),
    ).toBeInTheDocument();
  });

  it('calls onFilterChange when typing in search box', async () => {
    const { NotaFilters } = await import('./NotaFilters');
    const filters = makeFilters();
    const onChange = vi.fn();
    render(<NotaFilters filters={filters} onFilterChange={onChange} />);
    const input = screen.getByPlaceholderText(/buscar por fornecedor/i);
    fireEvent.change(input, { target: { value: 'empresa abc' } });
    expect(onChange).toHaveBeenCalledWith('searchTerm', 'empresa abc');
  });

  it('shows clear button when searchTerm has value', async () => {
    const { NotaFilters } = await import('./NotaFilters');
    const filters = makeFilters({ searchTerm: 'fornecedor x' });
    render(<NotaFilters filters={filters} onFilterChange={vi.fn()} />);
    // Clear button appears when searchTerm is set - look for the X button element
    const clearButtons = screen.getAllByRole('button');
    expect(clearButtons.length).toBeGreaterThan(0);
  });
});

