{isProcessing && <InvoiceProcessingLoader isVisible />}

{/* Header - Premium Style matching Eventos (Monochrome) */}
<div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6 w-full flex-wrap">
  <div className="flex items-center gap-3 min-w-max">
    {isMobile && (
      <Button data-mia-action="back"
        variant="ghost"
        size="icon"
        onClick={handleBack}
        className="h-12 w-12 -ml-3 rounded-full bg-white/50 dark:bg-white/10 hover:bg-white/80 dark:hover:bg-white/20 backdrop-blur-sm shadow-sm"
      >
        <ArrowLeft className="h-6 w-6 text-[#57715B] dark:text-[#E6DCCF]" />
      </Button>
    )}
    <div>
      <h1 className="text-4xl md:text-5xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF] font-serif mb-1 drop-shadow-sm">
        Compras
      </h1>
      <p className="text-xs md:text-sm text-[#8C7B6D] dark:text-[#9BA59C] font-medium tracking-widest uppercase opacity-80 pl-1">
        Notas fiscais e fornecedores
      </p>
    </div>
  </div>

  <div className="flex flex-col md:flex-row flex-wrap items-stretch md:items-center gap-3 w-full xl:w-auto justify-end">

    {/* Unified Date Filter */}
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-2">
        <Select
          value={dateFilterType}
          onValueChange={(v) => setDateFilterType(v as DateFilterType)}
        >
          <SelectTrigger className="w-[160px] h-10 rounded-xl border-[#57715B]/10 bg-white/50 dark:bg-black/20 backdrop-blur-sm text-sm font-medium text-[#57715B] dark:text-[#8FA893]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent className="rounded-xl border-[#57715B]/10">
            <SelectItem value="data_recebimento">Recebimento</SelectItem>
            <SelectItem value="created_at">Lançamento</SelectItem>
            <SelectItem value="data_nota">Emissão</SelectItem>
            <SelectItem value="data_vencimento">Vencimento</SelectItem>
          </SelectContent>
        </Select>

        <Popover>
          <PopoverTrigger asChild>
            <Button
              variant="outline"
              className={cn(
                "w-full md:w-[230px] justify-start text-left font-normal bg-white/50 dark:bg-black/20 border-[#57715B]/10 hover:bg-white/80 dark:hover:bg-black/40 backdrop-blur-sm rounded-xl",
                !dateFilterRange && "text-muted-foreground"
              )}
            >
              <CalendarIcon className="mr-2 h-4 w-4 text-[#57715B]" />
              {dateFilterRange?.from ? (
                dateFilterRange.to ? (
                  <span className="truncate text-sm">
                    {format(dateFilterRange.from, "dd/MM/yyyy", { locale: ptBR })} –{" "}
                    {format(dateFilterRange.to, "dd/MM/yyyy", { locale: ptBR })}
                  </span>
                ) : (
                  format(dateFilterRange.from, "dd/MM/yyyy", { locale: ptBR })
                )
              ) : (
                <span>Selecione um período</span>
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-auto p-0 border-[#57715B]/10 rounded-xl shadow-xl" align="end">
            <Calendar
              initialFocus
              mode="range"
              defaultMonth={dateFilterRange?.from}
              selected={dateFilterRange}
              onSelect={setDateFilterRange}
              numberOfMonths={2}
              locale={ptBR}
              className="p-3"
            />
          </PopoverContent>
        </Popover>
      </div>

      <div className="flex items-center gap-1 flex-wrap">
        {([
          { label: 'Hoje', from: today, to: today },
          { label: '7 dias', from: subDays(today, 6), to: today },
          { label: 'Este Mês', from: startOfMonth, to: today },
          { label: 'Mês Anterior', from: prevMonthStart, to: prevMonthEnd },
          { label: 'Este Ano', from: startOfYear(today), to: today },
        ] as { label: string; from: Date; to: Date }[]).map((p) => {
          const active =
            dateFilterRange?.from &&
            dateFilterRange?.to &&
            format(dateFilterRange.from, 'yyyy-MM-dd') === format(p.from, 'yyyy-MM-dd') &&
            format(dateFilterRange.to, 'yyyy-MM-dd') === format(p.to, 'yyyy-MM-dd');
          return (
            <Button
              key={p.label}
              variant="ghost"
              size="sm"
              onClick={() => setDateFilterRange({ from: p.from, to: p.to })}
              className={cn(
                "rounded-full text-xs h-7 px-3 font-medium border",
                active
                  ? "bg-[#57715B] text-white border-[#57715B]"
                  : "text-[#57715B] hover:bg-[#57715B]/10 bg-white/40 dark:bg-black/20 border-[#57715B]/10"
              )}
            >
              {p.label}
            </Button>
          );
        })}
      </div>
    </div>



    {!isMobile && (
      <>
        <Button
          onClick={() => { setIsAnalyticsView(!isAnalyticsView); setIsTransferView(false); }}
          variant={isAnalyticsView ? "default" : "outline"}
          data-mia-action="toggle-analytics"
          data-mia-description="Alternar visão de Analytics Avançado"
          className={cn(
            "h-10 px-4 whitespace-nowrap lg:px-6 rounded-full border-[#57715B]/20 font-semibold transition-all",
            isAnalyticsView
              ? "bg-[#57715B] text-white hover:bg-[#4A614D] shadow-md"
              : "text-[#57715B] hover:bg-[#57715B]/10"
          )}
        >
          <BarChart3 className="mr-2 h-4 w-4" />
          {isAnalyticsView ? "Voltar para Lista" : "Analytics Avançado"}
        </Button>

        <Button
          onClick={() => { setIsTransferView(!isTransferView); setIsAnalyticsView(false); }}
          variant={isTransferView ? "default" : "outline"}
          data-mia-action="toggle-transferencias"
          data-mia-description="Alternar Notas de Transferência (Momma↔Momma)"
          className={cn(
            "h-10 px-4 whitespace-nowrap lg:px-6 rounded-full border-[#C5A065]/20 font-semibold transition-all",
            isTransferView
              ? "bg-[#C5A065] text-white hover:bg-[#B08F55] shadow-md"
              : "text-[#C5A065] hover:bg-[#C5A065]/10 border-[#C5A065]/20"
          )}
        >
          <ArrowRightLeft className="mr-2 h-4 w-4" />
          {isTransferView ? "Voltar para Lista" : "Notas de Transferência"}
        </Button>

        {!isAnalyticsView && !isTransferView && (
          <Button
            onClick={() => setIsReportsModalOpen(true)}
            variant="outline"
            data-mia-action="open-relatorios"
            data-mia-description="Abrir modal de Relatórios"
            className="h-10 px-4 whitespace-nowrap lg:px-6 rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 font-semibold"
          >
            <BarChart3 className="mr-2 h-4 w-4" />
            Relatórios
          </Button>
        )}
      </>
    )}

    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          data-mia-action="nova-nota"
          data-mia-description="Abrir dropdown para criar nova Nota Fiscal (upload OCR ou manual)"
          className="h-10 px-6 rounded-full bg-[#57715B] hover:bg-[#4A614D] text-white shadow-lg shadow-[#57715B]/20 transition-all active:scale-95"
        >
          <Upload className="mr-2 h-4 w-4" />
          <span className="font-semibold">Nova Nota</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" sideOffset={8} className="w-56 rounded-xl border-[#57715B]/20">

